import React, { useEffect, useState, useContext } from 'react';
import './CartPage.css';
import { useNavigate } from 'react-router-dom';
import { UserContext } from './UserContext'; // Ensure correct path

const CartPage = () => {
  const navigate = useNavigate();
  const { userId } = useContext(UserContext); // Access the current user's ID
  const [cartItems, setCartItems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) {
      navigate('/login'); // Redirect if not logged in
    } else {
      fetchCartItems();
    }
  }, [userId]);

  const fetchCartItems = async () => {
    try {
      const response = await fetch(`/api/cart/${userId}`);
      const data = await response.json();
      setCartItems(data.cart || []);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching cart:', error);
      setLoading(false);
    }
  };

  const incrementQuantity = (index) => {
    const updatedCart = [...cartItems];
    updatedCart[index].quantity += 1;
    setCartItems(updatedCart);
  };

  const decrementQuantity = (index) => {
    const updatedCart = [...cartItems];
    if (updatedCart[index].quantity > 1) {
      updatedCart[index].quantity -= 1;
    } else {
      updatedCart.splice(index, 1); // Remove item if quantity reaches 0
    }
    setCartItems(updatedCart);
  };

  const subtotal = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const handleCheckout = () => {
    navigate('/Thankyou');
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="cart-container">
      <div className="cart-items">
        <h2>MY CART</h2>
        {cartItems.length === 0 ? (
          <p>Your cart is empty.</p>
        ) : (
          cartItems.map((item, index) => (
            <div key={item._id} className="item">
              <img src={item.imageUrl} alt={item.name} className="item-image" />
              <div className="item-details">
                <p className="item-name">{item.name}</p>
                <p>₹{item.price}</p>
                <div className="quantity-control">
                  <button className="quantity-button" onClick={() => decrementQuantity(index)}>-</button>
                  <span className="quantity">{item.quantity}</span>
                  <button className="quantity-button" onClick={() => incrementQuantity(index)}>+</button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
      {cartItems.length > 0 && (
        <div className="cart-subtotal">
          <h2>CART SUBTOTAL</h2>
          <div className="total">SUBTOTAL: ₹{subtotal}</div>
          <br />
          <input className="checkout-button" type="button" value="Checkout" onClick={() => navigate('/Thankyou')} />

        </div>
      )}
    </div>
  );
};

export default CartPage;
